<template><div class="min-h-screen bg-slate-50"><header class="bg-[#0d1d2d] p-5 text-white"><RouterLink to="/publications" class="font-semibold">← Data Bank</RouterLink></header><main class="mx-auto max-w-4xl px-5 py-8"><div v-if="pub"><div class="text-xs uppercase text-slate-500">{{pub.category||'Research'}}</div><h1 class="mt-2 text-3xl font-bold">{{pub.title}}</h1><p class="mt-4 text-lg text-slate-600">{{pub.summary}}</p><div class="mt-8 rounded-2xl border bg-white p-6"><div v-if="hasAccess"><div class="mb-4 flex flex-wrap items-center justify-between gap-3 text-xs font-semibold text-emerald-700"><span>ACCESS ACTIVE · EXPIRES {{access.expires_at ? new Date(access.expires_at).toLocaleString() : 'NEVER'}}</span><button v-if="access.can_download" @click="download" class="rounded-lg bg-[#0d1d2d] px-3 py-2 text-white">Download report</button></div><div class="prose max-w-none whitespace-pre-wrap">{{pub.content}}</div></div><div v-else><h2 class="text-xl font-semibold">Unlock the full report</h2><p class="mt-2 text-slate-600">Choose a reading or download package configured by the administrator.</p><div class="mt-5 grid gap-3 md:grid-cols-2"><div v-for="pkg in pub.packages" :key="pkg.id" class="rounded-xl border p-4"><div class="font-semibold">{{pkg.name}}</div><div class="mt-1 text-lg">UGX {{Number(pkg.amount_ugx).toLocaleString()}}</div><div class="text-xs text-slate-500">{{pkg.type==='reading' ? `${pkg.duration_minutes} minutes` : 'Download licence'}}</div><button @click="buy(pkg)" class="mt-3 w-full rounded-lg bg-[#0d1d2d] p-2 text-white">Buy access</button></div></div></div></div></div></main></div></template>
<script setup>
import {onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import api from '../api/client'
const route=useRoute(),pub=ref(null),hasAccess=ref(false),access=ref(null)
async function load(){const {data}=await api.get('/public/publications/'+route.params.slug);pub.value=data;const t=localStorage.getItem('public_token');if(t){api.defaults.headers.common.Authorization='Bearer '+t;try{const r=await api.get('/public/publications/'+route.params.slug+'/access');hasAccess.value=r.data.has_access;access.value=r.data.access;if(r.data.publication)pub.value={...pub.value,...r.data.publication}}catch(e){}}}
async function download(){const response=await api.get('/public/publications/'+route.params.slug+'/download',{responseType:'blob'});const url=URL.createObjectURL(response.data);const link=document.createElement('a');link.href=url;link.download=(pub.value.title||'report')+'.txt';link.click();URL.revokeObjectURL(url)}
async function buy(pkg){if(!localStorage.getItem('public_token')){alert('Please register/sign in first.');return}const phone=prompt('Enter your mobile money phone number');if(!phone)return;try{const {data}=await api.post('/payments/packages/'+pkg.id+'/initiate',{phone,method:'momo_manual'});const ref=prompt(data.instructions+'\nEnter last 5 characters of reference:');if(ref){await api.post('/payments/'+data.payment.id+'/reference',{last5_reference:ref});alert('Payment submitted. Admin verification will activate your access.')}}catch(e){alert(e.response?.data?.message||'Payment request failed')}}
onMounted(load)
</script>